package com.tecsup.producto.controller; import com.tecsup.producto.dto.ProductoRequest; import com.tecsup.producto.model.Producto; import com.tecsup.producto.service.ProductoService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/productos") public class ProductoController {private final ProductoService s;public ProductoController(ProductoService s){this.s=s;} @GetMapping public List<Producto> listar(){return s.listar();}@GetMapping("/{id}") public Producto obtener(@PathVariable Long id){return s.obtener(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Producto crear(@Valid @RequestBody ProductoRequest d){return s.crear(d);}@PutMapping("/{id}") public Producto actualizar(@PathVariable Long id,@Valid @RequestBody ProductoRequest d){return s.actualizar(id,d);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void eliminar(@PathVariable Long id){s.eliminar(id);}}
